"""Explicit, revision guarded relocation of documents generated by older builds.

The manifest and before/after copies are durable before any vault write. A retry
finishes the same plan rather than guessing whether an existing target is ours.
"""
from __future__ import annotations

import json
import re
import sqlite3
import uuid
from pathlib import Path

from .content_layout import legacy_destination
from .core import CoreError, revision


def _write_manifest(directory: Path, manifest: dict) -> None:
    target = directory / "manifest.json"
    temporary = directory / ".manifest.tmp"
    temporary.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
    temporary.replace(target)


def _check_scope(store, manifest, db=None):
    if str(store.vault) != manifest["vault_path"]:
        raise CoreError(409, "迁移期间知识库已切换，已保留备份，请回到原知识库后重试")
    if db is not None:
        row = db.execute("SELECT value FROM config WHERE key='vault_path'").fetchone()
        if not row or json.loads(row[0]) != manifest["vault_path"]:
            raise CoreError(409, "迁移期间知识库已切换，请重新读取")
        for repo_id, expected in manifest["repositories"].items():
            row = db.execute("SELECT data FROM repositories WHERE id=?", (repo_id,)).fetchone()
            repo = json.loads(row[0]) if row else {}
            if {key: repo.get(key) for key in ("vault_path", "commit")} != expected:
                raise CoreError(409, "迁移期间仓库范围或版本已变化，未覆盖现有资料")


def _rewrite_links(content, destinations, *, replace_link=None):
    def replace(match):
        if replace_link is not None:
            return replace_link(match)
        value = match[1]
        destination, separator, alias = value.partition("|")
        path, anchor, section = destination.partition("#")
        lookup = path if path.endswith(".md") else path + ".md"
        moved = destinations.get(lookup)
        if not moved:
            return match[0]
        if not path.endswith(".md"):
            moved = moved[:-3]
        return "[[" + moved + (anchor + section if anchor else "") + (separator + alias if separator else "") + "]]"
    def prose(text):
        # Exact-length delimiter pairs protect inline code, including spans
        # crossing a line break. Runs inside a matched code span are literal.
        runs = list(re.finditer(r"`+", text))
        following, last = {}, {}
        for index in range(len(runs) - 1, -1, -1):
            length = len(runs[index][0])
            following[index] = last.get(length)
            last[length] = index
        result, cursor, index = [], 0, 0
        while index < len(runs):
            opening = runs[index]
            escapes, preceding = 0, opening.start() - 1
            while preceding >= 0 and text[preceding] == "\\":
                escapes += 1
                preceding -= 1
            closing_index = following[index]
            if escapes % 2 or closing_index is None:
                index += 1
                continue
            closing = runs[closing_index]
            result.append(re.sub(r"\[\[([^\]\n]+)\]\]", replace, text[cursor:opening.start()]))
            result.append(text[opening.start():closing.end()])
            cursor, index = closing.end(), closing_index + 1
        result.append(re.sub(r"\[\[([^\]\n]+)\]\]", replace, text[cursor:]))
        return "".join(result)

    # CommonMark allows a closing fence longer than its opener. An unclosed
    # fence protects the rest of the document; neither case may rewrite code.
    result, pending, fence = [], [], None
    for line in content.splitlines(keepends=True):
        body = line.rstrip("\r\n")
        body = re.sub(r"^(?: {0,3}>[ \t]?)+", "", body)
        if fence:
            result.append(line)
            closing = re.fullmatch(r" {0,3}(`+|~+)[ \t]*", body)
            if closing and closing[1][0] == fence[0] and len(closing[1]) >= fence[1]:
                fence = None
            continue
        opening = re.match(r" {0,3}(`{3,}|~{3,})(.*)$", body)
        if opening and (opening[1][0] == "~" or "`" not in opening[2]):
            result.append(prose("".join(pending)))
            pending = []
            result.append(line)
            fence = (opening[1][0], len(opening[1]))
        elif body.startswith(("    ", "\t")):
            result.append(prose("".join(pending)))
            pending = []
            result.append(line)
        else:
            pending.append(line)
    result.append(prose("".join(pending)))
    return "".join(result)


def _plan(store):
    vault = store.vault
    candidates, skipped, repositories = [], [], {}
    with store._db() as db:
        for repo_id, raw in db.execute("SELECT id,data FROM repositories"):
            repo = json.loads(raw)
            if repo.get("vault_path") != str(vault):
                continue
            repositories[repo_id] = {key: repo.get(key) for key in ("vault_path", "commit")}
            for source_path, old, blob, saved_revision in db.execute(
                    "SELECT source_path,note_path,blob,revision FROM managed_notes WHERE repository_id=?", (repo_id,)):
                candidates.append({"kind": "source", "repository_id": repo_id, "source_path": source_path,
                                   "old": old, "new": legacy_destination(repo_id, "", old, source=True),
                                   "before_revision": saved_revision, "blob": blob})
            row = db.execute("SELECT value FROM config WHERE key=?", (f"ai_analysis:{repo_id}",)).fetchone()
            state = json.loads(row[0]) if row else {}
            if state.get("vault_path", str(vault)) != str(vault):
                continue
            for key, entry in state.get("notes", {}).items():
                old = entry.get("path", "")
                candidates.append({"kind": "business", "repository_id": repo_id, "key": key,
                                   "old": old, "new": legacy_destination(repo_id, key, old),
                                   "before_revision": entry.get("revision"), "before_entry": entry})
    owned = []
    for candidate in candidates:
        if candidate["old"] == candidate["new"]:
            continue
        try:
            old = store._path(candidate["old"], vault=vault)
            new = store._path(candidate["new"], vault=vault)
            if (not old.is_file() or old.is_symlink() or not candidate["before_revision"]
                    or revision(old.read_text(encoding="utf-8-sig")) != candidate["before_revision"]):
                skipped.append({"path": candidate["old"], "reason": "人工修改、缺失或无可核验版本"})
                continue
            if new.exists():
                skipped.append({"path": candidate["old"], "reason": "目标位置已存在，未覆盖"})
                continue
            candidate["content"] = old.read_text(encoding="utf-8-sig")
            owned.append(candidate)
        except (OSError, UnicodeError, CoreError):
            skipped.append({"path": candidate["old"], "reason": "路径或内容不可安全迁移"})
    destinations = {entry["old"]: entry["new"] for entry in owned}
    for entry in owned:
        entry["after_content"] = _rewrite_links(entry["content"], destinations)
        entry["after_revision"] = revision(entry["after_content"])
    return {"version": 1, "status": "planned", "vault_path": str(vault), "repositories": repositories,
            "entries": owned, "skipped": skipped}


def _update_metadata(store, manifest):
    with store._db() as db:
        db.execute("BEGIN IMMEDIATE")
        _check_scope(store, manifest, db)
        states = {}
        for entry in manifest["entries"]:
            repo_id = entry["repository_id"]
            if entry["kind"] == "source":
                row = db.execute("SELECT note_path,revision,blob FROM managed_notes WHERE repository_id=? AND source_path=?",
                                 (repo_id, entry["source_path"])).fetchone()
                before = (entry["old"], entry["before_revision"], entry["blob"])
                after = (entry["new"], entry["after_revision"], entry["blob"])
                if row not in (before, after):
                    raise CoreError(409, "迁移期间代码资料版本已变化，未覆盖")
                db.execute("UPDATE managed_notes SET note_path=?,revision=? WHERE repository_id=? AND source_path=?",
                           (entry["new"], entry["after_revision"], repo_id, entry["source_path"]))
            else:
                if repo_id not in states:
                    row = db.execute("SELECT value FROM config WHERE key=?", (f"ai_analysis:{repo_id}",)).fetchone()
                    states[repo_id] = json.loads(row[0]) if row else {}
                state = states[repo_id]
                current = state.get("notes", {}).get(entry["key"])
                updated = {**entry["before_entry"], "path": entry["new"], "revision": entry["after_revision"]}
                if current not in (entry["before_entry"], updated):
                    raise CoreError(409, "迁移期间业务笔记版本已变化，未覆盖")
                state["notes"][entry["key"]] = updated
        for repo_id, state in states.items():
            db.execute("UPDATE config SET value=? WHERE key=?", (json.dumps(state, ensure_ascii=False), f"ai_analysis:{repo_id}"))


def _metadata_committed(store, manifest):
    """A missing original is expected only after the entire metadata transaction."""
    with store._db() as db:
        for entry in manifest["entries"]:
            repo_id = entry["repository_id"]
            if entry["kind"] == "source":
                row = db.execute("SELECT note_path,revision FROM managed_notes WHERE repository_id=? AND source_path=?",
                                 (repo_id, entry["source_path"])).fetchone()
                if row != (entry["new"], entry["after_revision"]):
                    return False
            else:
                row = db.execute("SELECT value FROM config WHERE key=?", (f"ai_analysis:{repo_id}",)).fetchone()
                current = json.loads(row[0]).get("notes", {}).get(entry["key"], {}) if row else {}
                if (current.get("path"), current.get("revision")) != (entry["new"], entry["after_revision"]):
                    return False
    return True


def _finish(store, directory, manifest):
    vault = Path(manifest["vault_path"])
    _check_scope(store, manifest)
    committed = _metadata_committed(store, manifest)
    for index, entry in enumerate(manifest["entries"]):
        _check_scope(store, manifest)
        old, new = store._path(entry["old"], vault=vault), store._path(entry["new"], vault=vault)
        if not old.exists() and not committed:
            raise CoreError(409, "迁移期间原笔记已被删除，已保留备份，请人工核验")
        if old.exists() and revision(old.read_text(encoding="utf-8-sig")) != entry["before_revision"]:
            raise CoreError(409, "迁移期间原笔记发生人工修改，已保留原文和备份")
        content = (directory / "after" / f"{index}.md").read_text(encoding="utf-8")
        if new.exists():
            if new.is_symlink() or revision(new.read_text(encoding="utf-8-sig")) != entry["after_revision"]:
                raise CoreError(409, "迁移目标已发生变化，未覆盖现有笔记")
        else:
            if committed:
                raise CoreError(409, "迁移完成后的目标笔记已被删除，未自动恢复，请人工核验备份")
            if not old.exists():
                raise CoreError(409, "迁移原笔记已被删除，请依据备份人工核验")
            store._write_note(entry["new"], content, vault=vault)
    for entry in manifest["entries"]:
        for key, wanted in (("old", "before_revision"), ("new", "after_revision")):
            target = store._path(entry[key], vault=vault)
            # Before the metadata transaction, both copies must still exist.
            # On recovery after that transaction only old cleanup may have run.
            if not target.is_file():
                if key == "new" or not committed or target.exists() or target.is_symlink():
                    raise CoreError(409, "迁移期间笔记被删除或替换，已保留原文和备份")
                continue
            if target.is_symlink() or revision(target.read_text(encoding="utf-8-sig")) != entry[wanted]:
                raise CoreError(409, "迁移期间笔记发生变化，已保留备份")
    _update_metadata(store, manifest)
    manifest["status"] = "metadata_committed"
    _write_manifest(directory, manifest)
    retained = []
    for entry in manifest["entries"]:
        _check_scope(store, manifest)
        old = store._path(entry["old"], vault=vault)
        if old.exists():
            if revision(old.read_text(encoding="utf-8-sig")) == entry["before_revision"]:
                old.unlink()
            else:
                retained.append(entry["old"])
        store._signature.pop(entry["old"], None)
        store._signature.pop(entry["new"], None)
    manifest.update(status="completed", retained_old=retained)
    _write_manifest(directory, manifest)
    store.refresh()
    return {"moved": len(manifest["entries"]), "skipped": manifest["skipped"], "retained_old": retained,
            "manifest_path": str(directory / "manifest.json")}


def migrate_content_layout(store):
    """Relocate only unchanged, machine-owned legacy files in the selected vault."""
    with store._lock:
        vault = store.vault
        root = store.data_dir / "layout-migrations" / revision(str(vault))[:16]
        root.mkdir(parents=True, exist_ok=True)
        for manifest_path in sorted(root.glob("*/manifest.json")):
            manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
            if manifest["status"] != "completed":
                return _finish(store, manifest_path.parent, manifest)
        manifest = _plan(store)
        if not manifest["entries"]:
            return {"moved": 0, "skipped": manifest["skipped"], "retained_old": [], "manifest_path": None}
        directory = root / uuid.uuid4().hex
        (directory / "before").mkdir(parents=True)
        (directory / "after").mkdir()
        for index, entry in enumerate(manifest["entries"]):
            (directory / "before" / f"{index}.md").write_text(entry.pop("content"), encoding="utf-8")
            (directory / "after" / f"{index}.md").write_text(entry.pop("after_content"), encoding="utf-8")
        with sqlite3.connect(store.db_path) as source, sqlite3.connect(directory / "workspace.sqlite") as backup:
            source.backup(backup)
        _write_manifest(directory, manifest)
        return _finish(store, directory, manifest)
